import React, { useEffect, useState } from "react";
import { Button, RemoveButton } from "../../Buttons";
import ShareWithUser from "./ShareWithUser";
import PermissionDropdown from "./PermissionDropdown";
import { FaCheck } from "react-icons/fa";
import { BaseModalProps } from "../BaseModal/BaseModalProps";
import type { Permission } from "@shared/models/Permission";

export interface SharedUser {
  id: string;
  users: { email: string };
  permission: Permission;
}

interface ShareModalProps extends BaseModalProps {
  typeOfShare: string;
  sharedUsers: SharedUser[];
  isPublic: boolean;
  publicPermission: Permission;
  onTogglePublicShare: () => void;
  onSetPublicPermission: (permission: Permission) => void;
  shareWithUser: (email: string, permission: Permission) => void;
  onRevokeAccess: (userId: string) => void;
  onCopyLink: () => void;
}

const ShareModal: React.FC<ShareModalProps> = ({
  typeOfShare,
  sharedUsers,
  isPublic,
  publicPermission,
  onTogglePublicShare,
  onSetPublicPermission,
  shareWithUser,
  onRevokeAccess,
  onCopyLink,
  onClose,
}) => {
  const [isPublicLocal, setIsPublicLocal] = useState(isPublic);

  useEffect(() => {
    setIsPublicLocal(isPublic);
  }, [isPublic]);

  const handleTogglePublicShare = () => {
    setIsPublicLocal(!isPublicLocal);
    onTogglePublicShare();
  };
  return (
    <>
      <h2 className="text-lg font-semibold mb-4 min-w-[300px] dark:text-leaf-green-100">
        Share {typeOfShare}
      </h2>

      <div className="flex items-center justify-between mb-4 dark:text-leaf-green-100">
        <label className="text-sm">Make Public</label>
        <input
          type="checkbox"
          checked={isPublicLocal}
          onChange={handleTogglePublicShare}
          className="peer sr-only"
          id="custom-checkbox"
        />
        <label
          htmlFor="custom-checkbox"
          className="w-5 h-5 flex items-center justify-center border-2 border-gray-400 rounded-md cursor-pointer transition-all
          peer-checked:bg-leaf-green-600 peer-checked:border-leaf-green-600
          dark:border-gray-600 dark:peer-checked:bg-leaf-green-500 dark:peer-checked:border-leaf-green-500
          peer-focus-visible:ring-2 peer-focus-visible:ring-leaf-green-300 peer-focus-visible:ring-offset-1"
        >
          <FaCheck
            className={`w-4 h-4 text-white ${isPublicLocal ? "block" : "hidden"}`}
          />
        </label>
      </div>

      {isPublicLocal && (
        <div className="flex flex-col space-y-2 mb-4">
          <PermissionDropdown
            value={publicPermission}
            onChange={onSetPublicPermission}
          />
          <Button btnType="secondary" onClick={onCopyLink} className="w-full">
            Copy Public Link
          </Button>
        </div>
      )}

      <hr className="border-gray-700 my-4" />

      <ShareWithUser shareWithUser={shareWithUser} />

      <hr className="border-gray-700 my-4" />

      <h3 className="text-sm font-medium mb-2 dark:text-leaf-green-100">
        Shared Users
      </h3>
      <ul className="space-y-2 mb-4 dark:text-leaf-green-100">
        {sharedUsers.map((user) => (
          <li
            key={user.id}
            className="flex justify-between items-center bg-white dark:bg-gray-800 rounded-xs gap-2 p-2"
          >
            <span className="text-gray-700 dark:text-gray-200 text-sm">
              {user.users.email} - {user.permission}
            </span>
            <RemoveButton
              onClick={() => onRevokeAccess(user.id)}
              label={`Revoke access for ${user.users.email}`}
            />
          </li>
        ))}
      </ul>

      <Button onClick={onClose} className="w-full">
        Close
      </Button>
    </>
  );
};

export default ShareModal;
